<script setup lang="ts">
import {instrumentLabel,instrumentName} from '../utils/instrumentNames'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Activity,Pause,Play,RefreshCw,Radio,ScanLine} from 'lucide-vue-next'
import TongdaxinChart from '../components/TongdaxinChart.vue'
import OptionWatchPanel from '../components/OptionWatchPanel.vue'
import MonitorPanel from '../components/MonitorPanel.vue'
import {api,type InstrumentCatalog,type MarketMicrostructure} from '../services/api'
import {LIVE_PERIODS,liveApi,type IntradaySnapshot,type LiveFrequency} from '../services/live'
import {RefreshSchedule} from '../utils/refreshSchedule'
import {depthRadar} from '../utils/depthRadar'
import {formatNumber as n,formatTime} from '../utils/format'
import {useMarketStore} from '../stores/market'

const store=useMarketStore()
const activeTab=ref<'futures'|'options'|'monitors'>('futures')
const catalog=ref<InstrumentCatalog|null>(null),catalogError=ref(''),catalogLoading=ref(false)
const exchange=ref(''),product=ref(''),symbol=ref(''),search=ref(''),frequency=ref<LiveFrequency>(60)
const bars=ref<IntradaySnapshot|null>(null),depth=ref<MarketMicrostructure|null>(null)
const barsError=ref(''),depthError=ref(''),barsLoading=ref(false),depthLoading=ref(false)
const paused=ref(false),hidden=ref(document.hidden),clock=ref(Date.now()),lastReceived=ref<number|null>(null)
const products=computed(()=>catalog.value?.exchanges.flatMap(g=>g.instruments).filter(p=>(!exchange.value||p.exchange===exchange.value)&&(!search.value||`${p.name} ${p.rootSymbol} ${p.mainSymbol}`.toLowerCase().includes(search.value.trim().toLowerCase())))??[])
const selected=computed(()=>products.value.find(p=>p.mainSymbol===product.value))
const contracts=computed(()=>selected.value?[selected.value.mainSymbol,...selected.value.contracts]:[])
const period=computed(()=>LIVE_PERIODS.find(p=>p.value===frequency.value)?.label??'')
const calendarPeriod=computed(()=>typeof frequency.value==='string')
const radar=computed(()=>depthRadar(depth.value,clock.value))
const active=computed(()=>!paused.value&&!hidden.value&&!depthError.value&&radar.value.fresh)
const stateLabel=computed(()=>paused.value?'刷新已暂停':hidden.value?'后台暂停':depthError.value?'盘口连接待恢复':!depth.value?'等待真实盘口':radar.value.fresh?'近时行情':'缓存 / 行情未更新')
const bidWidth=computed(()=>radar.value.imbalance==null?50:(radar.value.imbalance+1)*50)
const largestDepth=computed(()=>Math.max(1,...radar.value.bids.map(d=>d.volume),...radar.value.asks.map(d=>d.volume)))
const alerts=computed(()=>{
  if(!active.value)return []
  const items:string[]=[]
  if(radar.value.imbalance!=null&&Math.abs(radar.value.imbalance)>=.6)items.push(`可见挂单偏${radar.value.imbalance>0?'买':'卖'} · ${n(radar.value.imbalance*100,0)}%`)
  if(radar.value.buyRatio!=null&&radar.value.buy+radar.value.sell>=10&&(radar.value.buyRatio>=.8||radar.value.buyRatio<=.2))items.push(`近 60 秒成交估算偏${radar.value.buyRatio>=.8?'买':'卖'} · 已分类 ${n(radar.value.buy+radar.value.sell,0)} 手`)
  return items
})
let alive=true,generation=0,barRequest=0,depthRequest=0,timer:number|undefined
const barSchedule=new RefreshSchedule(3000),depthSchedule=new RefreshSchedule(2000)
function message(error:unknown){return error instanceof Error?error.message:'行情暂不可用，请稍后重试。'}
async function loadCatalog(){
  if(catalogLoading.value)return
  catalogLoading.value=true;catalogError.value=''
  try{
    const data=await api.instruments();if(!alive)return;catalog.value=data
    if(!product.value){const all=data.exchanges.flatMap(g=>g.instruments);const initial=all.find(p=>p.mainSymbol===store.symbol||p.contracts.includes(store.symbol))??all[0];if(initial){exchange.value=initial.exchange;product.value=initial.mainSymbol;symbol.value=initial.contracts.includes(store.symbol)?store.symbol:initial.mainSymbol}}
  }catch(e){if(alive)catalogError.value=message(e)}finally{if(alive)catalogLoading.value=false}
}
async function loadBars(){
  if(!symbol.value||barsLoading.value||paused.value||hidden.value)return
  const ticket=++barRequest,version=generation,target=symbol.value,selectedFrequency=frequency.value;barsLoading.value=true
  try{const result=await liveApi.bars(target,selectedFrequency);if(!alive||ticket!==barRequest||version!==generation)return;if(result.symbol!==target||(typeof selectedFrequency==='number'?result.seconds!==selectedFrequency:result.period!==selectedFrequency))throw new Error('K 线与当前合约或周期不一致，已停止展示。');bars.value=result;barsError.value='';barSchedule.received(result.dataStatus)}
  catch(e){if(alive&&ticket===barRequest&&version===generation){barsError.value=message(e);barSchedule.failed()}}finally{if(alive&&ticket===barRequest)barsLoading.value=false}
}
async function loadDepth(){
  if(!symbol.value||depthLoading.value||paused.value||hidden.value)return
  const ticket=++depthRequest,version=generation,target=symbol.value;depthLoading.value=true
  try{const result=await api.microstructure(target);if(!alive||ticket!==depthRequest||version!==generation)return;if(result.symbol!==target)throw new Error('盘口与当前合约不一致，已停止展示。');depth.value=result;depthError.value='';lastReceived.value=Date.now();depthSchedule.received(result.dataStatus)}
  catch(e){if(alive&&ticket===depthRequest&&version===generation){depthError.value=message(e);depthSchedule.failed()}}finally{if(alive&&ticket===depthRequest)depthLoading.value=false}
}
function inspectAlert(target:string){
 const entry=catalog.value?.exchanges.flatMap(group=>group.instruments).find(item=>item.mainSymbol===target||item.contracts.includes(target))
 if(!entry){catalogError.value='预警合约暂不在当前目录，请核对原始合约，不自动替换交割月。';return}
 search.value='';exchange.value=entry.exchange;product.value=entry.mainSymbol;symbol.value=target;frequency.value=900;activeTab.value='futures'
}
function refresh(){barSchedule.reset();depthSchedule.reset();void loadBars();void loadDepth()}
function freezePending(){++barRequest;++depthRequest;barsLoading.value=false;depthLoading.value=false}
function visibility(){hidden.value=document.hidden;if(hidden.value)freezePending();else refresh()}
function togglePause(){paused.value=!paused.value;if(paused.value)freezePending();else refresh()}
watch([exchange,search],()=>{if(!products.value.some(p=>p.mainSymbol===product.value))product.value=products.value[0]?.mainSymbol??''})
watch(product,()=>{if(!contracts.value.includes(symbol.value))symbol.value=selected.value?.mainSymbol??''})
watch(symbol,()=>{++generation;++barRequest;++depthRequest;bars.value=null;depth.value=null;barsError.value='';depthError.value='';barsLoading.value=false;depthLoading.value=false;lastReceived.value=null;if(symbol.value){store.rememberSymbol(symbol.value);refresh()}})
watch(frequency,()=>{barSchedule.reset();++barRequest;bars.value=null;barsError.value='';barsLoading.value=false;void loadBars()})
onMounted(()=>{void loadCatalog();document.addEventListener('visibilitychange',visibility);timer=window.setInterval(()=>{clock.value=Date.now();if(paused.value||hidden.value)return;if(depthSchedule.due())void loadDepth();if(barSchedule.due())void loadBars()},1000)})
onUnmounted(()=>{alive=false;++generation;++barRequest;++depthRequest;window.clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>

<template>
 <div class="live-workspace">
  <header class="live-heading"><div><p class="live-kicker">LIVE MARKET / 行情观察台</p><h2>盯住价格，也看见价格背后的盘口。</h2><p>真实小周期 K 线 · 可见挂单 · Tick 成交增量</p></div><div class="live-actions"><span class="connection" :class="{online:active}" role="status"><i/>{{stateLabel}}</span><button @click="togglePause"><Play v-if="paused" :size="14"/><Pause v-else :size="14"/>{{paused?'继续刷新':'暂停刷新'}}</button><button :disabled="barsLoading&&depthLoading||paused" @click="refresh"><RefreshCw :size="14"/>刷新</button></div></header>
  <p v-if="catalogError" class="live-notice" role="alert">{{catalogError}} <button @click="loadCatalog">重试目录</button></p>
  <section class="live-selectors" aria-label="看盘合约选择"><label>交易所<select v-model="exchange" aria-label="看盘交易所"><option value="">全部交易所</option><option v-for="g in catalog?.exchanges??[]" :key="g.code" :value="g.code">{{g.name}}</option></select></label><label>查找品种<input v-model="search" aria-label="查找看盘品种" placeholder="代码 / 名称"/></label><label>品种<select v-model="product" aria-label="看盘品种"><option v-for="p in products" :key="p.mainSymbol" :value="p.mainSymbol">{{p.name}} · {{p.rootSymbol}}</option></select></label><label class="contract-select">观察合约<select v-model="symbol" aria-label="看盘合约"><option v-for="code in contracts" :key="code" :value="code">{{instrumentLabel(code)}}</option></select></label><button v-if="!catalog&&!catalogLoading" @click="loadCatalog">加载合约</button></section>
  <div class="live-quote-strip"><div><span class="instrument-name">{{symbol?instrumentName(symbol,selected?.name):'选择行情合约'}}</span><strong class="instrument-code">{{instrumentLabel(symbol)}}</strong><small>{{symbol===selected?.mainSymbol?'主连观察 · 跨合约序列':'交割合约观察'}}</small></div><div class="last-quote"><small>最新观测价</small><strong>{{n(depth?.lastPrice)}}</strong></div><div><small>盘口源时点</small><time>{{depth?formatTime(depth.dataTimestamp):'等待行情'}}</time></div><div><small>本页接收</small><time>{{lastReceived?formatTime(new Date(lastReceived).toISOString()):'—'}}</time></div><span class="source-name">{{depth?.source??'天勤行情通道'}}</span></div>
  <div class="live-tabs" role="tablist" aria-label="看盘与监控"><button role="tab" :aria-selected="activeTab==='futures'" @click="activeTab='futures'">期货行情</button><button role="tab" :aria-selected="activeTab==='options'" @click="activeTab='options'">对应期权行情</button><button role="tab" :aria-selected="activeTab==='monitors'" @click="activeTab='monitors'">期货机会预警</button></div>
  <div v-show="activeTab==='futures'" class="live-grid">
   <section class="live-chart" aria-label="多周期行情图">
    <header class="panel-header"><h3><Activity :size="16"/>多周期 K 线</h3><span>{{bars?.points.length??0}} 根 · {{bars?.dataStatus==='FRESH'&&!barsError?'近时数据':bars?'缓存数据':'等待订阅'}}</span></header>
    <div class="period-tabs" aria-label="K 线周期"><button v-for="p in LIVE_PERIODS" :key="p.value" :aria-pressed="frequency===p.value" :class="{chosen:frequency===p.value}" @click="frequency=p.value">{{p.label}}</button><small>近时行情每 3 秒读取 · 缓存或异常时自动降频 · 末根可能变化</small></div>
    <p v-if="barsError" class="inline-error" role="alert">{{barsError}} <button :disabled="paused" @click="loadBars">重试 K 线</button></p>
    <TongdaxinChart v-if="bars?.points.length" :key="symbol+'-'+frequency" :points="bars.points" :symbol="symbol" :display-name="`${instrumentName(symbol,selected?.name)} · ${period}`" :height="440" :initial-visible-bars="80" :drawing-tools="true" :drawing-key="symbol+'-'+frequency" :geometry="bars.geometry" :preserve-viewport-on-append="true" :time-label-mode="calendarPeriod?(frequency==='MONTH'?'month':'calendar'):'datetime-seconds'" default-sub-chart="vol"/>
    <div v-else class="chart-empty"><ScanLine :size="34"/><strong>{{barsLoading?'正在订阅真实 K 线…':'等待行情'}}</strong><p>仅显示行情源返回的 OHLCV，缺失时保持为空。</p></div>
    <footer class="chart-foot"><span>{{bars?.source??'天勤 TqSdk'}} · {{period}}</span><span>源行情：{{formatTime(bars?.dataTimestamp)}} · K 线时间为周期起点</span></footer>
    <p v-if="calendarPeriod" class="period-note">周线按自然周、月线按自然月汇总真实交易日日线，末根包含尚在变化的当前周期。均线按所选周期计算，历史不足 N 根显示 —。</p>
    <p v-if="bars?.message" class="inline-error">{{bars.message}}</p>
   </section>
   <aside class="depth-board" aria-label="实时盘口"><header class="panel-header"><h3><Radio :size="16"/>盘口深度</h3><span>买 {{radar.bidCoverage}} / 卖 {{radar.askCoverage}} 档可见</span></header><p v-if="depthError" class="inline-error" role="alert">{{depthError}} <button :disabled="paused" @click="loadDepth">重试盘口</button></p><div class="depth-head"><span>档位</span><span>价格</span><span>挂单 / 手</span></div><div v-for="level in [...(depth?.asks??[])].sort((a,b)=>b.level-a.level)" :key="'ask'+level.level" class="depth-line ask"><i :style="{width:(level.price!=null?level.volume/largestDepth*100:0)+'%'}"/><span>卖 {{level.level}}</span><strong>{{n(level.price)}}</strong><b>{{level.price==null?'—':n(level.volume,0)}}</b></div><div class="depth-mid"><span>买卖一价差</span><strong>{{n(radar.spread)}}</strong><small>价格单位</small></div><div v-for="level in depth?.bids??[]" :key="'bid'+level.level" class="depth-line bid"><i :style="{width:(level.price!=null?level.volume/largestDepth*100:0)+'%'}"/><span>买 {{level.level}}</span><strong>{{n(level.price)}}</strong><b>{{level.price==null?'—':n(level.volume,0)}}</b></div><p v-if="!depth" class="depth-empty">{{depthLoading?'正在等待真实盘口…':'暂无盘口数据'}}</p><p class="depth-note">缺失档位不补造。每 2 秒读取一次快照。</p></aside>
   <section class="radar-board" aria-label="盘口雷达"><header class="panel-header"><h3><ScanLine :size="16"/>盘口雷达</h3><span>{{active?'观测中':'提示已暂停 · 仅供查看快照'}}</span></header><div class="radar-metrics"><article><small>可见挂单不平衡</small><strong :class="radar.imbalance!=null&&radar.imbalance>=0?'buy-color':'sell-color'">{{radar.imbalance==null?'—':n(radar.imbalance*100,1)+'%'}}</strong><div class="balance-track"><i :style="{width:bidWidth+'%'}"/></div><p>买 {{n(radar.bidLots,0)}} / 卖 {{n(radar.askLots,0)}} 手</p></article><article><small>近 60 秒估算买向占比</small><strong>{{radar.buyRatio==null?'—':n(radar.buyRatio*100,1)+'%'}}</strong><p>买 {{n(radar.buy,0)}} · 卖 {{n(radar.sell,0)}} · 未定 {{n(radar.neutral,0)}} 手</p></article><article><small>近 60 秒最大 Tick 增量</small><strong>{{n(radar.maxTick,0)}}<em>手</em></strong><p>{{radar.ticks.length}} 个有成交增量的 Tick</p></article></div><div class="radar-events" aria-live="polite"><p v-for="item in alerts" :key="item"><i/>{{item}}</p><p v-if="!alerts.length">{{active?'当前观测窗口未达到偏向提示阈值。':'行情暂停、过时或连接失败时，不生成活跃提示。'}}</p></div><details><summary>雷达口径与阈值</summary><p>挂单不平衡 =（可见买量 − 可见卖量）/ 总可见挂单量，绝对值 ≥ 60% 时提示。成交方向按 Tick 价格与买卖一估算，买向量 / 已分类成交量 ≥ 80% 或 ≤ 20%、且已分类量 ≥ 10 手时提示。近 60 秒以盘口源时点为窗口终点，仅覆盖行情源保留的最近 Tick。</p><p>Tick 成交增量可能合并多笔成交，不能当作逐笔委托、真实主动买卖标志或主力资金流。盘口挂单可随时撤销，提示只描述已观测数据。</p></details></section>
   <section class="tape-board" aria-label="近期成交增量"><header class="panel-header"><h3>成交增量</h3><span>近 60 秒 · 最多显示 30 条</span></header><div class="tape-head"><span>时间</span><span>价格</span><span>手数</span><span>估算方向</span></div><div class="tape-scroll"><div v-for="trade in radar.ticks.slice(0,30)" :key="trade.id+trade.timestamp" class="tape-line" :class="trade.side==='BUY'?'buy-color':trade.side==='SELL'?'sell-color':''"><time>{{formatTime(trade.timestamp).slice(-8)}}</time><strong>{{n(trade.price)}}</strong><span>{{n(trade.volume,0)}}</span><small>{{trade.side==='BUY'?'买向':trade.side==='SELL'?'卖向':'未定'}}</small></div><p v-if="!radar.ticks.length" class="depth-empty">该观测窗口暂无可用成交增量</p></div></section>
  </div>
  <OptionWatchPanel v-if="activeTab==='options'" :future-symbol="symbol" :paused="paused||hidden"/>
  <MonitorPanel v-if="activeTab==='monitors'" asset-type="FUTURE" :symbol="symbol" :paused="paused||hidden" @inspect="inspectAlert"/>
  <p class="live-footnote">行情观察页 · 页面隐藏时暂停轮询 · 暂停页面刷新会保留最后一帧，后台监控仍持续运行；停止任务请在监控列表中暂停。</p>
 </div>
</template>

<style scoped>
.live-tabs{display:flex;gap:.4rem;flex-wrap:wrap;border-bottom:1px solid var(--live-line);padding-bottom:.7rem}.live-tabs button[aria-selected=true]{background:#305570;border-color:#7198af;color:#f1f7fa}
.period-note{padding:.7rem 1rem;margin:0;border-top:1px solid var(--live-line);font-size:.6rem;line-height:1.9;color:var(--live-muted)}
.live-workspace{--live-bg:#111a23;--live-panel:#182430;--live-line:#2a3a49;--live-muted:#94a5b6;--live-text:#e0e8ee;--live-buy:#ef8e83;--live-sell:#66c4a1;background:var(--live-bg);color:var(--live-text);border-radius:12px;padding:1.5rem;display:grid;gap:1rem;min-width:0}.live-heading{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}.live-kicker{font:.61rem var(--font-numeric);letter-spacing:.14em;color:#9cbdcc;margin:0}.live-heading h2{font:500 1.35rem var(--font-display);margin:.65rem 0}.live-heading p:last-child{font-size:.7rem;color:var(--live-muted);margin:.5rem 0}.live-actions{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}.live-workspace button{display:inline-flex;gap:.4rem;align-items:center;justify-content:center;cursor:pointer;color:var(--live-text);background:#203140;border:1px solid #3a5061;border-radius:5px;padding:.55rem .7rem;font-size:.68rem}.live-workspace button:disabled{opacity:.45;cursor:default}.connection{font-size:.65rem;display:flex;align-items:center;gap:.4rem;color:#b9bec2;margin-right:.4rem}.connection i{width:6px;height:6px;border-radius:50%;background:#b59d65}.connection.online i{background:#76d3b1;box-shadow:0 0 0 4px #76d3b115}.live-selectors{display:flex;align-items:end;gap:.8rem;flex-wrap:wrap;border:1px solid var(--live-line);border-radius:7px;background:var(--live-panel);padding:.9rem 1rem}.live-selectors label{display:grid;gap:.4rem;font-size:.62rem;color:var(--live-muted);flex:1;min-width:8rem}.live-selectors .contract-select{flex:1.3}.live-selectors input,.live-selectors select{font:.72rem var(--font-sans);color:var(--live-text);background:#101d28;border:1px solid #354b5d;border-radius:4px;padding:.6rem;min-width:0;width:100%}.live-quote-strip{display:flex;align-items:center;gap:1.6rem;padding:.6rem .3rem;flex-wrap:wrap}.live-quote-strip>div{display:grid;gap:.25rem}.instrument-name{font-size:.75rem}.instrument-code{font:.9rem var(--font-numeric);letter-spacing:.04em}.live-quote-strip small{color:var(--live-muted);font-size:.6rem}.live-quote-strip time{font:.68rem var(--font-numeric)}.last-quote strong{font:600 1.7rem var(--font-numeric);color:#eaf2f5}.source-name{color:var(--live-muted);font-size:.61rem;margin-left:auto}.live-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:1rem;min-width:0}.live-chart,.depth-board,.radar-board,.tape-board{min-width:0;background:var(--live-panel);border:1px solid var(--live-line);border-radius:7px;overflow:hidden}.panel-header{display:flex;align-items:center;justify-content:space-between;gap:.7rem;padding:.85rem 1rem;border-bottom:1px solid var(--live-line)}.panel-header h3{display:flex;align-items:center;gap:.5rem;font-size:.77rem;margin:0;font-weight:500}.panel-header>span{font:.56rem var(--font-numeric);color:var(--live-muted)}.period-tabs{display:flex;align-items:center;gap:.3rem;flex-wrap:wrap;padding:.6rem .8rem}.period-tabs button{border-color:transparent;background:transparent;color:var(--live-muted);padding:.35rem .5rem;font-size:.62rem}.period-tabs button.chosen{color:#dfeff6;background:#2d475a;border-color:#42647b}.period-tabs small{font-size:.56rem;color:var(--live-muted);margin-left:auto}.chart-foot{display:flex;justify-content:space-between;gap:.7rem;flex-wrap:wrap;padding:.7rem 1rem;color:var(--live-muted);font-size:.55rem;border-top:1px solid var(--live-line)}.chart-empty{min-height:440px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:1rem;color:var(--live-muted)}.chart-empty strong{font-size:.85rem;font-weight:500}.chart-empty p{font-size:.65rem;text-align:center;padding:0 1rem}.depth-head,.depth-line{display:grid;grid-template-columns:3.1rem 1fr 4.5rem;align-items:center;padding:0 .9rem;text-align:right;font:.67rem var(--font-numeric)}.depth-head{padding:.7rem .9rem;color:var(--live-muted);font-size:.57rem}.depth-line{position:relative;min-height:2.1rem}.depth-line>span:first-of-type,.depth-head span:first-child{text-align:left;color:var(--live